import re
def slugify(text):
    s = re.sub(r"[^a-z0-9]+", "-", str(text).lower())
    return s.strip("-")

import re
def parse_duration(text):
    text = str(text).strip()
    if text == "":
        return 0
    m = re.fullmatch(r"(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?", text)
    if not m or not any(m.groups()):
        raise ValueError(text)
    h, mi, s = (int(x) if x else 0 for x in m.groups())
    return h * 3600 + mi * 60 + s

def chunk(seq, n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError(n)
    seq = list(seq)
    return [seq[i:i + n] for i in range(0, len(seq), n)]

def clamp(x, lo, hi):
    if lo > hi:
        raise ValueError((lo, hi))
    return max(lo, min(hi, x))

def median(nums):
    nums = sorted(nums)
    if not nums:
        raise ValueError("empty")
    n = len(nums)
    mid = n // 2
    if n % 2:
        return float(nums[mid])
    return (nums[mid - 1] + nums[mid]) / 2.0

def dedupe(items):
    out = []
    for x in items:
        if x not in out:
            out.append(x)
    return out

def rotate(items, k):
    items = list(items)
    if not items:
        return []
    k %= len(items)
    return items[-k:] + items[:-k] if k else items

def human_bytes(n):
    if n < 1000:
        return "%d B" % n
    for unit in ("KB", "MB", "GB", "TB"):
        n /= 1000.0
        if n < 1000 or unit == "TB":
            s = ("%.1f" % n).rstrip("0").rstrip(".")
            return "%s %s" % (s, unit)

def parse_query(qs):
    out = {}
    if not qs:
        return out
    for part in qs.split("&"):
        if part == "":
            continue
        k, _, v = part.partition("=")
        out[k.replace("+", " ")] = v.replace("+", " ")
    return out

def format_cents(c):
    sign = "-" if c < 0 else ""
    c = abs(int(c))
    return "%s$%s.%02d" % (sign, format(c // 100, ","), c % 100)

def merge_intervals(intervals):
    out = []
    for s, e in sorted([list(x) for x in intervals]):
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

import re
def word_freq(text, n):
    if n <= 0:
        return []
    words = re.findall(r"[a-z]+", str(text).lower())
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:n]

def rle_encode(s):
    if not s:
        return ""
    out = []
    prev = s[0]
    n = 1
    for ch in s[1:]:
        if ch == prev:
            n += 1
        else:
            out.append("%s%d" % (prev, n))
            prev, n = ch, 1
    out.append("%s%d" % (prev, n))
    return "".join(out)

import re
def rle_decode(s):
    if s == "":
        return ""
    parts = re.findall(r"([A-Za-z])(\d+)", s)
    if "".join(a + b for a, b in parts) != s:
        raise ValueError(s)
    out = []
    for ch, num in parts:
        n = int(num)
        if n <= 0:
            raise ValueError(s)
        out.append(ch * n)
    return "".join(out)

def top_k(nums, k):
    if k <= 0:
        return []
    return sorted(nums, reverse=True)[:k]

def roman_to_int(text):
    vals = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    s = str(text).upper()
    if not s:
        raise ValueError(text)
    total = 0
    for i, c in enumerate(s):
        if c not in vals:
            raise ValueError(text)
        v = vals[c]
        if i + 1 < len(s) and vals[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total

def int_to_roman(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 1 or n > 3999:
        raise ValueError(n)
    table = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
             (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
    out = []
    for v, s in table:
        while n >= v:
            out.append(s)
            n -= v
    return "".join(out)

def flatten(seq):
    out = []
    for x in seq:
        if isinstance(x, (list, tuple)):
            out.extend(flatten(x))
        else:
            out.append(x)
    return out

def caesar(text, k):
    out = []
    for c in str(text):
        if c.isalpha() and c.isascii():
            base = ord("A") if c.isupper() else ord("a")
            out.append(chr((ord(c) - base + k) % 26 + base))
        else:
            out.append(c)
    return "".join(out)

def binary_search_index(sorted_list, target):
    lo, hi = 0, len(sorted_list) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_list[mid] == target:
            return mid
        if sorted_list[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def is_anagram(a, b):
    def key(s):
        return sorted(c for c in str(s).lower() if c.isalnum())
    return key(a) == key(b)

def most_common(items):
    items = list(items)
    if not items:
        raise ValueError("empty")
    counts, first = {}, {}
    for i, x in enumerate(items):
        counts[x] = counts.get(x, 0) + 1
        first.setdefault(x, i)
    return max(counts, key=lambda x: (counts[x], -first[x]))

def max_subarray_sum(nums):
    nums = list(nums)
    if not nums:
        raise ValueError("empty")
    best = cur = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best

def transpose(matrix):
    rows = [list(r) for r in matrix]
    if not rows:
        return []
    if any(len(r) != len(rows[0]) for r in rows):
        raise ValueError("ragged")
    return [list(col) for col in zip(*rows)]

def valid_brackets(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for c in str(text):
        if c in "([{":
            stack.append(c)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
    return not stack

def mode_value(nums):
    nums = list(nums)
    if not nums:
        raise ValueError("empty")
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    best = max(counts.values())
    return min(x for x, c in counts.items() if c == best)

import re
def snake_case(text):
    s = re.sub(r"[^a-z0-9]+", "_", str(text).lower())
    return s.strip("_")

def initials(name):
    parts = [p for p in str(name).split() if p]
    return "".join(p[0].upper() + "." for p in parts)

def split_even(nums):
    evens, odds = [], []
    for x in nums:
        (evens if x % 2 == 0 else odds).append(x)
    return evens, odds

def second_largest(nums):
    values = sorted(set(nums))
    if len(values) < 2:
        raise ValueError("need two distinct values")
    return values[-2]

def cumulative_sum(nums):
    out, total = [], 0
    for x in nums:
        total += x
        out.append(total)
    return out

def zip_longest_pad(a, b, fill):
    a, b = list(a), list(b)
    out = []
    for i in range(max(len(a), len(b))):
        out.append((a[i] if i < len(a) else fill, b[i] if i < len(b) else fill))
    return out

def fizzbuzz_list(n):
    out = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            out.append("FizzBuzz")
        elif i % 3 == 0:
            out.append("Fizz")
        elif i % 5 == 0:
            out.append("Buzz")
        else:
            out.append(str(i))
    return out

def group_anagrams(words):
    out = {}
    for w in words:
        key = "".join(sorted(str(w).lower()))
        out.setdefault(key, []).append(str(w))
    for key in out:
        out[key].sort()
    return out

def pairs_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return (seen[target - x], i)
        seen.setdefault(x, i)
    return None

def compress_ranges(nums):
    nums = list(nums)
    if not nums:
        return ""
    out, start, prev = [], nums[0], nums[0]
    for x in nums[1:]:
        if x == prev + 1:
            prev = x
            continue
        out.append(str(start) if start == prev else "%d-%d" % (start, prev))
        start = prev = x
    out.append(str(start) if start == prev else "%d-%d" % (start, prev))
    return ",".join(out)
